using System.ComponentModel;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

const string modelId = "gpt-4o-mini-2024-07-18";

// ── Research notebook (shared state for the note-taking tool) ───────────────
var notebook = new List<(string Title, string Content)>();

// ── Tool definitions ────────────────────────────────────────────────────────
var searchWebTool = AIFunctionFactory.Create(SearchWeb,
    "search_web",
    "Searches the web for a query and returns results as text.");

var addNoteTool = AIFunctionFactory.Create(AddNote,
    "add_note",
    "Saves a research note with a title and content.");

var getNotesTool = AIFunctionFactory.Create(GetNotes,
    "get_notes",
    "Retrieves all research notes collected so far.");

// ── Build the chat client via MEAI ──────────────────────────────────────────
IChatClient chatClient = new OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// ── Create the agent (Microsoft Agent Framework) ────────────────────────────
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a thorough research agent. When the user gives you a topic:
        1. Use search_web multiple times to explore different aspects of the topic.
        2. After each search, use add_note to record the key findings.
        3. Once you have gathered enough information, use get_notes to review your notes.
        4. Finally, write a well-structured summary with sections and bullet points.
        Always cite which searches contributed to each finding.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: [searchWebTool, addNoteTool, getNotesTool]);

// ── Interactive loop ────────────────────────────────────────────────────────
Console.WriteLine("🔬 Research Agent Ready");
Console.WriteLine("Type a topic to research, or 'quit' to exit.\n");

while (true)
{
    Console.Write("> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) ||
        topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    var runOptions = new ChatClientAgentRunOptions
    {
        ChatOptions = new ChatOptions
        {
            Temperature = 0.2f,
            MaxOutputTokens = 2048,
        },
    };

    Console.WriteLine($"\n📡 Researching \"{topic}\" …\n");

    try
    {
        await foreach (var update in agent.RunStreamingAsync(
            $"Research the following topic thoroughly and provide a summary: {topic}",
            session: null,
            runOptions))
        {
            Console.Write(update.Text);
        }
    }
    catch (Exception ex)
    {
        Console.WriteLine($"\n❌ Error: {ex.Message}");
    }

    Console.WriteLine("\n");
}

Console.WriteLine("Goodbye!");
return;

// ═══════════════════════════════════════════════════════════════════════════
// Tool implementations
// ═══════════════════════════════════════════════════════════════════════════

async Task<string> SearchWeb(
    [Description("The search query")] string query)
{
    Console.WriteLine($"  🔍 Searching: \"{query}\"");
    using var http = new HttpClient();
    http.Timeout = TimeSpan.FromSeconds(10);
    try
    {
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
        var json = await http.GetStringAsync(url);

        using var doc = JsonDocument.Parse(json);
        var root = doc.RootElement;
        var results = new List<string>();

        // Abstract / instant answer
        var abstractText = root.GetProperty("AbstractText").GetString();
        if (!string.IsNullOrWhiteSpace(abstractText))
            results.Add($"Summary: {abstractText}");

        var abstractSource = root.GetProperty("AbstractSource").GetString();
        if (!string.IsNullOrWhiteSpace(abstractSource))
            results.Add($"Source: {abstractSource}");

        // Related topics
        if (root.TryGetProperty("RelatedTopics", out var related))
        {
            foreach (var item in related.EnumerateArray().Take(5))
            {
                if (item.TryGetProperty("Text", out var text) &&
                    !string.IsNullOrWhiteSpace(text.GetString()))
                {
                    results.Add($"- {text.GetString()}");
                }
            }
        }

        return results.Count > 0
            ? string.Join("\n", results)
            : "No detailed results found. Try a more specific query.";
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}. Try a different query.";
    }
}

string AddNote(
    [Description("A short title for the note")] string title,
    [Description("The note content with key findings")] string content)
{
    notebook.Add((title, content));
    Console.WriteLine($"  📝 Note saved: \"{title}\"");
    return $"Note #{notebook.Count} saved: \"{title}\"";
}

string GetNotes()
{
    if (notebook.Count == 0)
        return "No notes have been saved yet.";

    Console.WriteLine($"  📋 Reviewing {notebook.Count} note(s)");
    var formatted = notebook.Select((n, i) =>
        $"Note #{i + 1} — {n.Title}\n{n.Content}");
    return string.Join("\n\n", formatted);
}

